// Normaliza os argumentos e rejeita horários no passado (reason 'passado').
const a = $input.first().json || {};
const start_at = a.start_at || null;
let futuro = true;
if (start_at) { futuro = new Date(start_at) > new Date(); }
const barber_id = (a.barber_id === null || a.barber_id === undefined || a.barber_id === '') ? null : a.barber_id;
return [{ json: {
  wa_id: a.wa_id,
  client_name: a.client_name || '',
  service_id: a.service_id ?? null,
  barber_id,
  start_at,
  futuro
} }];

// Valida janela no expediente e calcula end_at = start_at + duration_minutes.
const v = $('Validar Dados Iniciais').first().json;
const base = { wa_id: v.wa_id, client_name: v.client_name, service_id: v.service_id, barber_id: v.barber_id, start_at: v.start_at };
if (!v.start_at) return [{ json: { ...base, ok: false, reason: 'fora-expediente' } }];
if (!v.futuro) return [{ json: { ...base, ok: false, reason: 'passado' } }];
const serv = $('Buscar Serviço').first().json;
if (!serv || !serv.duration_minutes) return [{ json: { ...base, ok: false, reason: 'duracao-indisponivel' } }];
const exp = $('Buscar Expediente do Horário').first().json;
if (!exp || exp.closed) return [{ json: { ...base, ok: false, reason: 'fora-expediente', duration_minutes: serv.duration_minutes } }];
function paraMin(t) { if (!t) return null; const p = String(t).split(':').map(Number); return p[0] * 60 + p[1]; }
const start = new Date(v.start_at);
const end = new Date(start.getTime() + Number(serv.duration_minutes) * 60000);
const sMin = start.getHours() * 60 + start.getMinutes();
const eMin = end.getHours() * 60 + end.getMinutes();
const openM = paraMin(exp.open_time);
const closeM = paraMin(exp.close_time);
if (sMin < openM || eMin > closeM) return [{ json: { ...base, ok: false, reason: 'duracao-indisponivel', duration_minutes: serv.duration_minutes } }];
const bIni = paraMin(exp.break_start);
const bFim = paraMin(exp.break_end);
if (bIni !== null && bFim !== null && sMin < bFim && eMin > bIni) return [{ json: { ...base, ok: false, reason: 'fora-expediente', duration_minutes: serv.duration_minutes } }];
return [{ json: { ...base, ok: true, reason: null, duration_minutes: serv.duration_minutes, service_name: serv.name, end_at: end.toISOString() } }];

// Consome o cliente recém-upsertado e a pré-checagem de conflito (espelho da EXCLUDE gist).
const valid = $('Validar Janela e Calcular Fim').first().json;
const cliente = $('Upsert Cliente').first().json || {};
const conflito = $('Verificar Conflito').first().json || null;
const motivo = (conflito && conflito.id) ? 'conflito' : null;
return [{ json: { ...valid, client_id: cliente.id, motivo } }];

// Monta o retorno de sucesso da §4.
const linha = $('Inserir Agendamento').first().json || {};
const valid = $('Validar Janela e Calcular Fim').first().json;
return [{ json: { ok: true, appointment_id: linha.id, start_at: valid.start_at, end_at: valid.end_at } }];
